import{_ as t,c as e,o as a,ag as r}from"./chunks/framework.Cycwnjj0.js";const s="/assets/amazon-comparisons-table-from-azonpress-dashboard.Br9OmeDl.webp",n="/assets/create-your-first-comparison-table-button.DOyPogyQ.webp",i="/assets/add-new-comparison-table-button.q8GmTfEl.webp",p="/assets/create-new-comparison-table-pop-up-page.B7wMCuxE.webp",c="/assets/add-more-product-for-comparisons.Dz5YEkPF.webp",l="/assets/update-_-preview-button.jPmoaKQm.webp",m="/assets/preview-of-comparison-table.BsKQyg-r.webp",y=JSON.parse('{"title":"How to Create an Amazon Comparison Table with AzonPress","description":"","frontmatter":{},"headers":[],"relativePath":"guide/amazon-comparison-tables/how-to-create-an-amazon-comparison-table.md","filePath":"guide/amazon-comparison-tables/how-to-create-an-amazon-comparison-table.md"}'),g={name:"guide/amazon-comparison-tables/how-to-create-an-amazon-comparison-table.md"};function u(d,o,h,b,w,f){return a(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="how-to-create-an-amazon-comparison-table-with-azonpress" tabindex="-1">How to Create an Amazon Comparison Table with AzonPress <a class="header-anchor" href="#how-to-create-an-amazon-comparison-table-with-azonpress" aria-label="Permalink to &quot;How to Create an Amazon Comparison Table with AzonPress&quot;">​</a></h1><p>AzonPress offers a wonderful feature named <strong>Comparison Table</strong> that will allow your customers to quickly and easily compare key features, prices, and reviews of Amazon Products which will help them to make purchasing decisions. This article will guide you through <strong>creating Comparison Table/s</strong> with AzonPress for <strong>Amazon</strong> products on your <strong>WordPress</strong> website.</p><h2 id="create-a-comparison-table" tabindex="-1">Create A Comparison Table <a class="header-anchor" href="#create-a-comparison-table" aria-label="Permalink to &quot;Create A Comparison Table&quot;">​</a></h2><p>To learn how to create a comparison table with AzonPress, follow the steps with the screenshots below –</p><p>First, go to the <strong>Amazon Comparisons</strong> from the <strong>WordPress Sidebar</strong> or <strong>Comparison Tables</strong> from the <strong>Amazon</strong> dropdown in the top right corner of the <strong>AzonPress Navbar.</strong></p><p><strong>Remember</strong>, you need to <strong>connect</strong> your <strong>AzonPress</strong> with your <strong>Amazon Associate Account API</strong> to get the <strong>Amazon dropdown</strong> option in the <strong>AzonPress Navbar</strong>.</p><p><img src="'+s+'" alt="Amazon Comparisons Table option from AzonPress Dashboard"></p><p>Click on the <strong>Create Your First Comparison Table</strong> button.</p><p><img src="'+n+'" alt="Create your first comparison table button"></p><p>If you have already created comparison tables with AzonPress, you&#39;ll find the <strong>Add New Comparison Table</strong> button to create a new table. Click on it and a pop-up page will appear.</p><p><img src="'+i+'" alt="Add new comparison table button"></p><p>Give your table a <strong>Title</strong>. Now <strong>search</strong> for your desired <strong>products</strong> with <strong>keywords</strong> and a list of products will appear on the window.</p><p><strong>Remember</strong>, you need to <strong>connect</strong> your <strong>AzonPress</strong> with your <strong>Amazon Associate Account API</strong> to fetch <strong>Amazon product data</strong>.</p><p>Now, select the ones you want to compare, or can select all by clicking the <strong>Select All</strong> button. Finally, click on the <strong>Create Table</strong> button.</p><p><img src="'+p+'" alt="Create new comparison table Pop-up Page"></p><p>To add more products to your comparison table again if needed, go to the bottom of the page and press <strong>Search Product using Amazon API</strong> button. It will take you to the product search pop-up page again.</p><p><img src="'+c+'" alt="Add more product for comparisons"></p><p>Now, you can see that a default comparison table has been created in your back end.</p><p>If you want to learn more about <strong>Customizing</strong> your <strong>Comparison Tables</strong>, read this <a href="/guide/amazon-comparison-tables/customization-of-comparison-tables.html">Documentation</a>. Also, to learn about <strong>Customizing</strong> tables through <strong>Appearance Settings</strong>, read this <a href="/guide/miscellaneous/appearance-settings.html">Documentation</a>.</p><p>Once you are done customizing the table, click the <strong>Update</strong> or <strong>Update Setting</strong> button, and your table will be ready to display.</p><p>Also, see how your table will appear on your front end by clicking the <strong>Preview</strong> button.</p><p><img src="'+l+'" alt="Update Preview button"></p><p>Here is a preview of what your table will look like in the front end.</p><p><img src="'+m+'" alt="Preview of Comparison table"></p><p>This is how you can create a comparison table efficiently using AzonPress!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',27)])])}const z=t(g,[["render",u]]);export{y as __pageData,z as default};
